import{flow,earnOpening}from './opening-flow.mjs';
import test from 'node:test';import assert from 'node:assert/strict';import{SCALE,fitSprite,motionPose,PartyTrail,viewLayout,personFor,objectiveFor}from '../presentation.js';import{Battle,makeEnemy}from '../battle.js?v=5.6.0';import{World}from '../world.js';import fs from 'node:fs';
test('sprite fitting preserves source aspect and respects both bounds',()=>{for(let[w,h]of[[90,140],[160,110],[100,100]]){let fit=fitSprite(w,h,60,70);assert.ok(Math.abs(fit.width/fit.height-w/h)<1e-12);assert.ok(fit.width<=70&&fit.height<=60);}});
test('stride is distance based, frame rate independent and retains facing at rest',()=>{let p={x:0,y:0},q={...p};for(let i=0;i<60;i++)p=motionPose(p,-(i+1)/60,-(i+1)/60);for(let i=0;i<30;i++)q=motionPose(q,-(i+1)/30,-(i+1)/30);assert.ok(Math.abs(p.phase-q.phase)<1e-10);assert.equal(p.back,true);assert.equal(p.facing,-1);let still=motionPose(p,p.x,p.y);assert.equal(still.moving,false);assert.equal(still.back,true);assert.equal(still.facing,-1);assert.equal(still.phase,p.phase);});
test('all four run phases occur and each actor moves independently',()=>{let a={x:0,y:0},b={x:0,y:0},frames=new Set();for(let i=1;i<40;i++){a=motionPose(a,i*.05,0);frames.add(a.frame);b=motionPose(b,0,0);}assert.equal(frames.size,4);assert.equal(b.phase,0);assert.equal(b.moving,false);});
test('trail samples turn through the actual corner instead of cutting across it',()=>{let t=new PartyTrail(0,0);for(let i=1;i<=10;i++)t.record(i*.1,0);for(let i=1;i<=10;i++)t.record(1,i*.1);assert.deepEqual(t.sample(.5),{x:1,y:.5});let p=t.sample(1.5);assert.ok(Math.abs(p.x-.5)<1e-12);assert.equal(p.y,0);t.record(30,30);assert.deepEqual(t.sample(.8),{x:30,y:30});});
test('portrait and landscape reserve space for touch controls and dialogue',()=>{for(const[w,h]of[[360,740],[390,780],[844,390],[1363,936]])for(const battle of[false,true]){let v=viewLayout(w,h,{touch:true,dialog:!battle,battle});assert.ok(v.centerY>v.top);assert.ok(v.centerY<h-v.controlZone);assert.ok(v.zoom>.5&&v.zoom<1.5);assert.ok(SCALE.building/SCALE.hero>3);}});
test('story puzzle characters are people, including the smaller child',()=>{assert.equal(personFor({type:'puzzle',steps:[{prompt:'ROOK: How do we mend this?'}]}).row,2);assert.equal(personFor({type:'puzzle',steps:[{prompt:'NELL: Listen! That is Papa!'}]}).child,true);assert.equal(personFor({type:'puzzle',steps:[{prompt:'Relay sequence?'}]}),null);});
test('opening objectives follow earned delivery, repair and recruitment',()=>{let h=flow(),w=h.w;assert.match(objectiveFor(w).label,/Mara/);h.use(w.objects().find(o=>o.type==='npc'));assert.match(objectiveFor(w).label,/Rook/);h.use(w.objects().find(o=>o.type==='portal'));assert.match(objectiveFor(w).label,/Rook/);h.use(w.objects().find(o=>o.type==='puzzle'&&o.bit===0));h.choose();assert.match(objectiveFor(w).label,/Nell/);let earned=earnOpening();assert.equal(earned.w.state.party.length,3);});
test('line attack damage now matches the finite visible telegraph',()=>{const e=makeEnemy('boss',1,0,true),b=new Battle({heroes:[],enemies:[e]}),i={shape:'line',fromX:0,fromY:0,x:3,y:0};assert.ok(b.intentHits(e,i,{x:5,y:0}));assert.equal(b.intentHits(e,i,{x:-1,y:0}),false);assert.equal(b.intentHits(e,i,{x:7,y:0}),false);assert.equal(b.intentHits(e,i,{x:2,y:1}),false);});
